import{_ as r,l,o as a,c as s,v as n,p as i,x as t,d,i as u,S as c}from"./chunks/framework.InCnrqk-.js";const k=JSON.parse('{"title":"Claude 3.5 Sonnet / Haiku","description":"","frontmatter":{"title":"Claude 3.5 Sonnet / Haiku","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/claude-35.md","filePath":"llm/claude-35.md","lastUpdated":1789023840000}'),p={name:"llm/claude-35.md"};function h(S,e,m,A,g,f){const o=l("Mermaid");return a(),s("div",null,[e[1]||(e[1]=n('<h1 id="claude-3-5-sonnet-haiku" tabindex="-1">Claude 3.5 Sonnet / Haiku <a class="header-anchor" href="#claude-3-5-sonnet-haiku" aria-label="Permalink to &quot;Claude 3.5 Sonnet / Haiku&quot;">​</a></h1><div class="epigraph"><p>3.5 Sonnet 以中档的速度与价格超过当时的 Opus；升级档把 SWE-bench Verified 从 33.4% 拉到 49.0%，并首次把「看屏幕、点鼠标」以公开测试版交给开发者。</p><footer>—— 综合 Anthropic 2024-06-21 与 2024-10-22 博文，以及 Model Card Addendum: Claude 3.5 Haiku and Upgraded Claude 3.5 Sonnet</footer></div><p>Claude 3.5 不是一张卡里的一个检查点。2024 年 6 月 21 日发布的 <strong>Claude 3.5 Sonnet</strong> 是 3.5 家族的第一枪：研究生级推理（GPQA）、本科知识（MMLU）、编码（HumanEval）上刷新当时公开对比，并在 claude.ai 上线 <strong>Artifacts</strong>——代码、文档、网页设计出现在对话旁的专用窗，可即时编辑。2024 年 10 月 22 日的增补卡与博文给出 <strong>升级版 3.5 Sonnet</strong>（<code>claude-3-5-sonnet-20241022</code>）与 <strong>Claude 3.5 Haiku</strong>：升级档在智能体编码与工具上再跳一截，并公开测试 <strong>computer use</strong>；Haiku 在许多评测上追平旧旗舰 Opus，速度仍接近上一代 Haiku。上下文默认仍是 200K 量级。本篇按两份公开材料分列检查点，<strong>不编参数量</strong>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>3 月的 <a href="/llm/claude-3-card">Claude 3</a> 把智能峰值放在 Opus 上，中档 Sonnet 留给企业吞吐量。三个月后 Anthropic 要证明：中档可以在智能上超过旧旗舰，从而把「日常编码与分析」的默认模型从 Opus 换下来，降低延迟与账单。6 月卡要交的是语言、视觉、编码与写作语调，而不是桌面智能体。</p><p>10 月要交的是智能体闭环。SWE-bench Verified 测的是真实仓库 issue：读代码、改补丁、过测试。τ-bench 测的是带工具的多步任务（航司、零售）。OSWorld 测的是只看截图、在真实桌面应用里点选。人在 OSWorld 约 72% 成功；当时其他模型的截图-only 分数很低。computer use 把模型输出定义成鼠标键盘动作，错误会变成真实副作用，安全评测必须单独做。</p><h3 id="artifacts-是产品表面-不是新模态" tabindex="-1">Artifacts 是产品表面，不是新模态 <a class="header-anchor" href="#artifacts-是产品表面-不是新模态" aria-label="Permalink to &quot;Artifacts 是产品表面，不是新模态&quot;">​</a></h3><p>Artifacts 把模型生成的代码与页面从气泡里拆出来，变成可迭代的工作区。它不改变 tokenizer，也不等于视觉输入。6 月的能力跃迁在模型检查点；Artifacts 改变的是人如何消费输出。写 3.5 时不要把侧栏写成「多模态架构」。</p><p><span class="marginnote">6 月公开数字（Anthropic 发布口径）：GPQA Diamond 59.4%，SWE-bench Verified 33.4%，HumanEval 92.0%。10 月升级档 SWE-bench Verified <strong>49.0%</strong>；3.5 Haiku SWE-bench <strong>40.6%</strong>，超过 6 月的 3.5 Sonnet。τ-bench 航司 52%→62%、零售 62%→69%（升级档相对原 3.5 Sonnet）。引用必须钉日期戳。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>6 月材料几乎不谈训练配方，沿用 Claude 3 的 CAI / 反馈叙事，强调评测与产品。10 月增补卡给出 computer use 的操作定义：模型解释截图，生成 GUI 命令（移动光标、点击、键入），完成跨应用工作流。评测只给截图，不用 OSWorld 可选的无障碍树文本。标准 15 步预算下升级 3.5 Sonnet 平均成功率 <strong>14.9%</strong>；把步数放到 50、并优化提示后到 <strong>22%</strong>，说明一部分失败是交互预算而不是单步感知。人类 72.36%。工具使用另测 SWE-bench 与 τ-bench；Haiku 知识截止写为 2024 年 7 月。</p><p>安全：computer use 放在 <strong>ASL-2</strong> 框架下，卡片称未发现灾难性风险指标。新增第一方与独立第三方的多模态红队。增补卡明确<strong>不把 OpenAI o1 家族列入对比表</strong>，因为大量预响应计算与「普通前向」不可比。越狱、提示注入在控制电脑时变成「按恶意页面指示点按钮」，缓解必须含环境沙箱与权限，而不仅是拒答。</p>',12)),(a(),i(c,null,{default:t(()=>[u(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20C3%5B%22Claude%203%20Opus%2FSonnet%2FHaiku%22%5D%20--%3E%20S35%5B%222024-06%EF%BC%9A3.5%20Sonnet%20%2B%20Artifacts%22%5D%0A%20%20S35%20--%3E%20UP%5B%222024-10%EF%BC%9A%E5%8D%87%E7%BA%A7%203.5%20Sonnet%22%5D%0A%20%20S35%20--%3E%20H35%5B%222024-10%EF%BC%9A3.5%20Haiku%22%5D%0A%20%20UP%20--%3E%20CU%5B%22computer%20use%20%E6%B5%8B%E8%AF%95%E7%89%88%22%5D%0A%20%20CU%20--%3E%20OSW%5B%22OSWorld%20%E6%88%AA%E5%9B%BE%2014.9%25%20%2F%2050%20%E6%AD%A5%2022%25%22%5D%0A%20%20UP%20--%3E%20SWE%5B%22SWE-bench%20Verified%2049.0%25%22%5D%0A%20%20H35%20--%3E%20SWE2%5B%22Haiku%20SWE-bench%2040.6%25%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=n('<h3 id="屏幕动作是工具-不是「模型有一双手」" tabindex="-1">屏幕动作是工具，不是「模型有一双手」 <a class="header-anchor" href="#屏幕动作是工具-不是「模型有一双手」" aria-label="Permalink to &quot;屏幕动作是工具，不是「模型有一双手」&quot;">​</a></h3><p>API 把 computer、文本编辑器、shell 等定义成工具 schema；执行层由开发者搭。模型只提议动作，真实点击发生在用户的沙箱虚拟机里。OSWorld 的 14.9% 是在这一接口上的任务成功率，远低于人，博文也写早期笨拙、易错。50 步预算提高成功，同时提高被注入与失控循环的暴露面。不要把演示视频里的流畅操作外推成基准满分。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>6 月 3.5 Sonnet 的机制主张是<strong>同一价格档的能力上移</strong>：发布材料写它比 Claude 3 Opus 更快约一倍量级、价格同中档，同时在 GPQA/MMLU/HumanEval 上刷新。这改变默认路由：多数对话不必上 Opus。视觉与写作语调（幽默、细指令）被写成同期改善，没有公开新的视觉编码器公式。</p><p>10 月的机制主张是<strong>视觉-动作闭环</strong>：截图 → 语言/坐标动作 → 环境 → 新截图。价值信号在评测里是任务脚本的成功与否，训练侧未公开是否用了这些环境做 RL。Haiku 3.5 表明「小档」可以吃到上一旗舰的编码与推理，使延迟敏感路径不必回退到 Claude 3 Haiku 的智能水平。知识截止与视觉（Haiku 曾先以文本上线、图像稍后）以当时博文为准，不要假设三档功能集时刻对齐。</p><p><span class="marginnote">computer use 的坐标与分辨率、滚动、延迟点击，都是工程接口问题。模型卡评的是「在给定工具下能否完成 OSWorld 任务」，不是操作系统驱动。换一套桌面或只给 DOM，分数会变。</span></p><h3 id="与-3-7-的边界" tabindex="-1">与 3.7 的边界 <a class="header-anchor" href="#与-3-7-的边界" aria-label="Permalink to &quot;与 3.7 的边界&quot;">​</a></h3><p><a href="/llm/claude-37">Claude 3.7</a> 把「延长思考」做成显式模式；3.5 升级档仍是普通前向（可多步工具循环，但没有 budget_tokens 思维块）。用 3.7 的 SWE-bench 去比较 3.5 时，必须声明思考预算。本篇停在 2024 年 10 月增补卡。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>两份材料均无参数。SWE-bench 对脚手架极度敏感，Anthropic 报的 33.4/49.0/40.6 是他们的 pass@1 设定。computer use 应在隔离环境、低风险任务上试，官方自己这样建议。Artifacts 只在 claude.ai 一类产品表面，API 用户要自己做工作区。3.5 Sonnet 后来有过更多快照与下线，引用生产系统须写模型 ID。不要把 2025 年 Sonnet 4 的 1M 窗口写进 3.5。</p><p>提示注入、恶意网页、凭据页面，是 computer use 的一等风险，增补卡单独讨论。只开「能点鼠标」而不做域名白名单，等于把 ASL-2 评测环境换成开放互联网。3.5 Haiku 的定位是把旧 Opus 级的部分智能放到低延迟档，用来承接客服、审核与分类，而不是替代升级档 Sonnet 的仓库级智能体；两档共用 3.5 家族名，评测与工具权限仍应分开选。</p><p><span class="marginnote">出处：Anthropic，<em>Introducing Claude 3.5 Sonnet</em>（2024-06-21）；<em>Introducing computer use, a new Claude 3.5 Sonnet, and Claude 3.5 Haiku</em>（2024-10-22）；<em>Model Card Addendum: Claude 3.5 Haiku and Upgraded Claude 3.5 Sonnet</em>。参数量未公开。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>2024-06：3.5 Sonnet 超过当时 Opus 的多项智能指标，并上线 Artifacts。</li><li>2024-10：升级 Sonnet SWE-bench 49.0%，Haiku 40.6%；computer use 截图版 OSWorld 14.9%（50 步 22%）。</li><li>安全分级仍为 ASL-2；对比表排除 o1 类长思考模型。</li><li>检查点必须用日期戳区分；无公开参数量。</li><li>出处：上述 Anthropic 博文与增补模型卡。</li></ul>',14))])}const C=r(p,[["render",h]]);export{k as __pageData,C as default};
